'use strict';
const marketFilters=new Map();
function parseProbabilityThreshold(value){if(value==null||String(value).trim()==='')return null;const n=Number(String(value).replace(',','.'));return Number.isFinite(n)?Math.max(0,Math.min(100,n)):null;}
let minimumProbability=null;try{minimumProbability=parseProbabilityThreshold(localStorage.getItem('oddscope-min-probability'));}catch{}

const forecastEntries=new Map(),forecastQueue=[];let forecastActive=0;
const predictionKey=(provider,sport,league,id)=>`${provider}:${sport}:${league}:${id}`;
function recordById(id){return feed.records.find(r=>r.eventId===id&&r.provider===state.provider);}
function formatChance(p){if(p<.001)return '<0,1%';if(p>.999)return '>99,9%';return (p*100).toLocaleString('es-ES',{maximumFractionDigits:1})+'%';}
function getForecast(id){const r=recordById(id);return r?forecastEntries.get(predictionKey(r.provider,r.sport,r.league,id)):null;}
function ensureForecast(record){
 const provider=record.provider,sport=record.sport,league=record.league,key=predictionKey(provider,sport,league,record.eventId),prior=forecastEntries.get(key);if(prior&&Date.now()-prior.at<30000)return prior.promise;
 let complete;const promise=new Promise(resolve=>{complete=resolve;});const entry={status:'loading',at:Date.now(),promise,data:null,error:null};forecastEntries.set(key,entry);forecastQueue.push({key,record,provider,sport,league,entry,complete});pumpForecasts();return promise;
}
function taskVisible(t){return state.provider===t.provider&&feed.records.some(r=>r.eventId===t.record.eventId&&r.provider===t.provider);}
function pumpForecasts(){while(forecastActive<2&&forecastQueue.length){const t=forecastQueue.shift();if(!taskVisible(t)){forecastEntries.delete(t.key);t.complete(null);continue;}forecastActive++;runForecast(t).finally(()=>{forecastActive--;pumpForecasts();});}}
async function runForecast(t){try{const r=await fetch(`/api/triunfobet/probabilities?id=${t.record.eventId}`,{cache:'no-store'});const data=await r.json();if(!r.ok)throw new Error(data.message||'No se pudo consultar los porcentajes.');if(data.eventId!==t.record.eventId)throw new Error('El cálculo no corresponde a este encuentro.');t.entry.data=data;t.entry.status='ready';t.complete(data);}catch(err){t.entry.status='error';t.entry.error=err.message;t.complete(null);}finally{if(taskVisible(t)&&['explorar','favoritos','comparar'].includes(state.view)){const card=$('#real-match-list')?.querySelector(`.mini-forecast[data-real-event="${t.record.eventId}"]`);if(card)card.outerHTML=miniForecast(t.record);}if(taskVisible(t)&&state.drawer===t.record.eventId)renderForecastPanel(t.record.eventId);}}
function queueForecasts(records){for(const record of records)ensureForecast(record);}
let forecastObserver=null;
function observeForecasts(records){forecastObserver?.disconnect();if(typeof IntersectionObserver==='undefined'){queueForecasts(records.slice(0,20));return;}const byId=new Map(records.map(r=>[String(r.eventId),r]));forecastObserver=new IntersectionObserver(entries=>{for(const entry of entries){if(!entry.isIntersecting)continue;const record=byId.get(entry.target.dataset.realEvent);forecastObserver.unobserve(entry.target);if(record){ensureForecast(record);entry.target.outerHTML=miniForecast(record);}}},{rootMargin:'200px 0px'});for(const card of $('#real-match-list').querySelectorAll('.mini-forecast[data-real-event]')){const record=byId.get(card.dataset.realEvent);if(record){const entry=getForecast(record.eventId);if(!entry||Date.now()-entry.at>30000)forecastObserver.observe(card);}}}

function miniForecast(record){const entry=getForecast(record.eventId);if(!entry)return `<button class="mini-forecast unavailable" data-real-event="${record.eventId}">Ver logros</button>`;if(entry.status==='loading')return `<button class="mini-forecast loading" data-real-event="${record.eventId}">Consultando…</button>`;const f=entry.data;return `<button class="mini-forecast" data-real-event="${record.eventId}"><strong>${f?.resultCount??0} logros</strong><small>Crear Apuesta</small></button>`;}
function allForecastGroups(f){return f.available?f.groups:[];}
function forecastDetailsHTML(f){return `<details class="forecast-method"><summary>Detalles del cálculo</summary><p>${escapeHTML(f.method)}</p><p>Cuotas consultadas el ${escapeHTML(new Date(f.fetchedAt).toLocaleString('es-ES',{timeZone:'America/Caracas'}))} (Venezuela).</p></details>`;}
function renderForecastPanel(id){
 const mount=$('#real-forecast');if(!mount||state.drawer!==id)return;const entry=getForecast(id);if(!entry||entry.status==='loading'){mount.innerHTML=`<div class="notice">${icon('clock')}Calculando…</div>`;return;}if(entry.status==='error'){mount.innerHTML='<div class="data-error">No se pudieron consultar los logros.</div>';return;}const f=entry.data;const groups=allForecastGroups(f);const count=groups.reduce((n,g)=>n+g.rows.length,0);
 mount.innerHTML=`<section class="forecast-intro"><h3><span id="forecast-result-count" aria-live="polite">${count} logros</span>${f.marketScope==='bet-builder'?' · Crear Apuesta':''}</h3>${groups.some(g=>g.rows.some(r=>r.p!=null))?`<p class="forecast-scope">${f.kind==='implied-odds'?'Probabilidad implícita · incluye margen':'Estimación inicial · prepartido'}${f.eventStatus==='finished'?' · retrospectiva':f.eventStatus==='inprogress'?' · sin ajuste en directo':''}</p>`:'<p class="forecast-scope">'+escapeHTML(f.marketScope==='bet-builder'?f.message:'Sin estimación')+'</p>'}</section>${groups.length?`<div id="market-categories" class="market-categories"></div><div class="drawer-toolbar"><label class="search">${icon('search')}<input id="forecast-search" aria-label="Buscar logro o mercado" placeholder="Buscar cualquier logro disponible…"></label><select id="forecast-group" aria-label="Categoría de probabilidades"><option value="all">Todos los logros</option>${groups.map(g=>`<option value="${escapeHTML(g.id)}">${escapeHTML(g.name)}</option>`).join('')}</select><div class="probability-filter"><label for="forecast-min-probability">Probabilidad mayor que</label><span class="probability-input"><input id="forecast-min-probability" type="number" inputmode="decimal" min="0" max="100" step="0.1" placeholder="Sin mínimo" aria-label="Probabilidad mayor que, en porcentaje"><span aria-hidden="true">%</span></span><button id="forecast-reset-probability" type="button">Quitar filtro</button></div></div><div class="forecast-columns"><span>LOGRO / MERCADO</span><span>${f.kind==='implied-odds'?'IMPLÍCITA':'ESTIMACIÓN'}</span><span>${f.kind==='implied-odds'?'CUOTA':'HISTÓRICO'}</span></div><div id="forecast-markets"></div>`:''}${forecastDetailsHTML(f)}`;
 if(groups.length){const key=state.provider+':'+id;const filters=marketFilters.get(key)||{query:'',group:'all',category:'all'};marketFilters.set(key,filters);$('#forecast-search').value=filters.query;$('#forecast-group').value=groups.some(g=>g.id===filters.group)?filters.group:'all';const categories=[...new Set(groups.map(marketCategory))];const names={all:'Todos',match:'Partido',players:'Jugadores',corners:'Córners',cards:'Tarjetas',shots:'Remates',fouls:'Faltas',trends:'Tendencias'};$('#market-categories').innerHTML=['all',...categories].map(c=>`<button class="chip ${filters.category===c?'active':''}" data-market-category="${c}">${names[c]||c}</button>`).join('');const update=()=>renderForecastMarkets(f,filters.query,filters.group,filters.category,minimumProbability);$('#forecast-min-probability').value=minimumProbability??'';$('#forecast-reset-probability').hidden=minimumProbability===null;$('#forecast-min-probability').oninput=e=>{minimumProbability=parseProbabilityThreshold(e.target.value);try{if(minimumProbability===null)localStorage.removeItem('oddscope-min-probability');else localStorage.setItem('oddscope-min-probability',String(minimumProbability));}catch{}$('#forecast-reset-probability').hidden=minimumProbability===null;update();};$('#forecast-min-probability').onchange=e=>{e.target.value=minimumProbability??'';};$('#forecast-reset-probability').onclick=()=>{$('#forecast-min-probability').value='';$('#forecast-min-probability').dispatchEvent(new Event('input'));};$('#forecast-search').oninput=e=>{filters.query=e.target.value;update();};$('#forecast-group').onchange=e=>{filters.group=e.target.value;const selected=groups.find(g=>g.id===filters.group);filters.category=selected?marketCategory(selected):'all';for(const button of $('#market-categories').querySelectorAll('button'))button.classList.toggle('active',button.dataset.marketCategory===filters.category);update();};$('#market-categories').onclick=e=>{const b=e.target.closest('[data-market-category]');if(!b)return;filters.category=b.dataset.marketCategory;filters.group='all';$('#forecast-group').value='all';for(const button of $('#market-categories').querySelectorAll('button'))button.classList.toggle('active',button.dataset.marketCategory===filters.category);update();};update();}
}
function marketCategory(g){return g.id==='published-trends'?'trends':g.category||'match';}
function renderForecastMarkets(f,query,group,category='all',minProbability=minimumProbability){const q=query.trim().toLocaleLowerCase('es');const groups=allForecastGroups(f).filter(g=>(group==='all'||g.id===group)&&(category==='all'||marketCategory(g)===category)).map(g=>({...g,rows:g.rows.filter(r=>(minProbability===null||(typeof r.p==='number'&&Number.isFinite(r.p)&&r.p>minProbability/100))&&`${r.label} ${r.market||''} ${g.name}`.toLocaleLowerCase('es').includes(q))})).filter(g=>g.rows.length);const total=allForecastGroups(f).reduce((n,g)=>n+g.rows.length,0),shown=groups.reduce((n,g)=>n+g.rows.length,0);if($('#forecast-result-count'))$('#forecast-result-count').textContent=shown===total?`${total} logros`:`${shown} de ${total} logros`;$('#forecast-markets').innerHTML=groups.length?groups.map(g=>`<section class="market-group"><h3>${escapeHTML(g.name)}<span>${g.conditional?escapeHTML(g.conditional)+' · ':''}${g.rows.length} resultados</span></h3>${g.rows.map(r=>`<div class="forecast-row"><span>${escapeHTML(r.label)}${r.market?`<small class="market-context">${escapeHTML(r.market)}</small>`:''}</span><strong>${r.p==null?'—':escapeHTML(formatChance(r.p))}</strong><span class="history-frequency" title="${f.kind==='implied-odds'?'Cuota decimal publicada; porcentaje implícito con margen':r.history?escapeHTML(r.history.scope+' · Wilson 95%: '+r.history.interval95.map(formatChance).join(' – ')):r.publishedRate!=null?'Frecuencia histórica publicada; no es probabilidad futura':'Sin frecuencia comparable'}">${f.kind==='implied-odds'?(r.odds!=null?escapeHTML(r.odds.toLocaleString('es-ES',{maximumFractionDigits:4})):'Suspendida / sin cuota'):r.publishedRate!=null?`${escapeHTML(formatHistorical(r.publishedRate))}`:r.history?`${escapeHTML(formatHistorical(r.history.rate))}<small>${r.history.hits}/${r.history.n} partidos</small>`:'—'}</span></div>`).join('')}</section>`).join(''):'<div class="empty">Sin resultados.</div>';}
